// Call the target function to obtain a read-only, null-terminated C string
const char *p = hw_name();
// Enforce non-null contract for meaningful pooling; if NULL, bail
if (!p) { FUZZ_BAIL(); }

// Validate that the returned pointer looks like a C string by requiring a NUL within a bounded scan
// This avoids reading unbounded memory in case the implementation is buggy.
unsigned int max_scan = 4096; // keep small for fuzzer perf
unsigned int len = 0;
for (; len < max_scan; ++len) {
    if (p[len] == '\0') { break; }
}
if (len == max_scan) { FUZZ_BAIL(); }

// Expose as an opaque pointer in the object pool; never modify or free this memory
void *name_ptr = (void *)p;
// Tag attributes so downstream stubs (if any) can treat it as read-only C string
FUZZ_SET_ATTR_STR(name_ptr, "opaque_kind", "const_cstring");
FUZZ_SET_ATTR_INT(name_ptr, "strlen", (int)len);
FUZZ_SET_ATTR_INT(name_ptr, "readonly", 1);
// Validation: ensured non-null and NUL-terminated within a safe bound; returned as opaque, read-only output.

// Generate arbitrary int operands; they are already representable as int
int a = *FUZZ_PARAM(int);
int b = *FUZZ_PARAM(int);

// Invoke the function under test; overflow (if any) follows int arithmetic rules
int result = hw_sum(a, b);
(void)result; // result is intentionally unused; we only validate API robustness
